using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
[Trait("Tier","Heavy")]public sealed class NpcPurposeTests
{
    static readonly EntityId Friend=new("created:routine-0");
    internal static ContractWorld Start(bool companions=false,string? policy=NewGameNpcRoutine.PurposePolicy)
    {
        var old=NpcContinuingTests.Start(companions:companions);var d=old.NewGame!;
        return NewGameWorld.Create(d.Start,d.Registered,d.Selected.Value,old.Seed,NewGameWorld.CompactPersonalAuthority,d.HistoricalCatalog,policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,LocalWorkDemand.Policy,developmentPolicy:CharacterDevelopment.Policy,companionPolicy:companions?PersonalCompanions.Policy:null);
    }
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.Code+":"+r.VisibleReason);
    static WorldSession PracticingCompanion(){var s=new WorldSession(Start(true));Good(s.ManageCompanion(new(new("request:purpose-agree"),Friend,CompanionAction.Agree,20),s.PlayerControl,s.Revision));At(s,20);Assert.Contains(s.DiagnosticSnapshot().Tasks,t=>t.Executor==Friend&&t.Action==ActionKind.Train&&t.Execution==ExecutionPhase.Running);return s;}
    static void Commission(WorldSession s)=>Good(s.ManageCompanion(new(new("request:purpose-duty"),Friend,CompanionAction.Inspect),s.PlayerControl,s.Revision));
    [Fact]public void IdlePracticeUsesSharedTasksAndOnlyActualCompletionAwards(){var s=new WorldSession(Start());At(s,20);var w=s.DiagnosticSnapshot();Assert.Equal(7,w.Requests.Count(r=>r.Intent.Action==ActionKind.Train));Assert.DoesNotContain(w.Development!.Awards,a=>w.Tasks.Single(t=>t.Id==a.Task).Action==ActionKind.Train);Assert.DoesNotContain(w.Requests,r=>r.Intent.Actor==s.PlayerControl);At(s,1900);w=s.DiagnosticSnapshot();Assert.Equal(7,w.Development!.Awards.Count(a=>w.Tasks.Single(t=>t.Id==a.Task).Action==ActionKind.Train));Assert.All(w.Development.Awards.Where(a=>w.Tasks.Single(t=>t.Id==a.Task).Action==ActionKind.Train),a=>Assert.Equal(1800,a.Seconds));new WorldSession(w);}
    [Fact]public void NoPracticeEveryTickAndAtMostOncePerPersonPerDay(){var s=new WorldSession(Start());At(s,1900);int n=s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Action==ActionKind.Train);At(s,80000);Assert.Equal(n,s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Action==ActionKind.Train));At(s,88400);var w=s.DiagnosticSnapshot();Assert.Equal(n*2,w.Requests.Count(r=>r.Intent.Action==ActionKind.Train));Assert.All(w.Requests.Where(r=>r.Intent.Action==ActionKind.Train).GroupBy(r=>r.Intent.Actor),g=>Assert.All(g.Zip(g.Skip(1)),x=>Assert.True(x.Second.CreatedAt-x.First.CreatedAt>=86400)));}
    [Fact]public void AcceptedCooperationInterruptsDiscretionaryPracticeWithoutExperience(){var s=PracticingCompanion();var first=s.DiagnosticSnapshot().Tasks.Single(t=>t.Executor==Friend&&t.Action==ActionKind.Train);Commission(s);At(s,40);var w=s.DiagnosticSnapshot();Assert.Equal(ExecutionPhase.Stopped,w.Tasks.Single(t=>t.Id==first.Id).Execution);Assert.Equal("npc-duty-priority",w.Tasks.Single(t=>t.Id==first.Id).InternalReason);Assert.DoesNotContain(w.Development!.Awards,a=>a.Task==first.Id);var q=w.Companions!.Orders.Single(q=>q.Input.Id.Value=="request:purpose-duty");Assert.Equal(ExecutionPhase.Completed,w.Tasks.Single(t=>t.RequestId==q.Task!.RequestId).Execution);Assert.Single(w.Requests,r=>r.Intent.Actor==Friend&&r.Intent.Action==ActionKind.Train);new WorldSession(w);}
    [Fact]public void PracticingPersonRemainsLocallyAvailableForConversation(){var s=PracticingCompanion();var row=s.CompanionView().Single(c=>c.Person==Friend);Assert.True(row.Nearby);Assert.Equal(new EntityId("site:castle"),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Friend).Site);}
    [Fact]public void InvalidCooperationDoesNotInterruptOrChangePractice(){var s=PracticingCompanion();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(new(new("request:invalid-purpose-trip"),Friend,CompanionAction.TravelTogether,Destination:"missing-place"),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ACompanionTripPreemptsPracticeAndKeepsOneRealJourney(){var s=PracticingCompanion();Good(s.ManageCompanion(new(new("request:purpose-travel"),Friend,CompanionAction.TravelTogether,Destination:"kofu"),s.PlayerControl,s.Revision));At(s,25);var w=s.DiagnosticSnapshot();Assert.Contains(w.Tasks,t=>t.Executor==Friend&&t.Action==ActionKind.Train&&t.Execution==ExecutionPhase.Stopped);Assert.Single(w.Branches!.Journeys,j=>j.Actor==Friend);Assert.DoesNotContain(w.Development!.Awards,a=>a.Actor==Friend&&w.Tasks.Single(t=>t.Id==a.Task).Action==ActionKind.Train);}
    [Fact]public void HiddenRoadTruthDoesNotChoosePracticeOrInspection(){var a=Start();var b=ContractJson.Copy(a);string edge=BranchRoutes.GraphEdges(a).First(e=>e.From=="castle"||e.To=="castle").Id;b.Couriers=b.Couriers! with{Conditions=[new(1,edge,true)]};var x=new WorldSession(a);var y=new WorldSession(b);At(x,1);At(y,1);Assert.Equal(ContractJson.Write(x.DiagnosticSnapshot().NpcWork),ContractJson.Write(y.DiagnosticSnapshot().NpcWork));}
    [Fact]public void PurposePolicyRequiresDevelopment(){var w=Start();w.NewGame=w.NewGame! with{DevelopmentPolicy=null};w.Development=null;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(NewGameNpcRoutine.Policy)][InlineData(NewGameNpcRoutine.ContinuingPolicy)]
    public void OldNpcPoliciesNeverAcquirePractice(string policy){var s=new WorldSession(Start(policy:policy));At(s,1900);Assert.DoesNotContain(s.DiagnosticSnapshot().Requests,r=>r.Intent.Action==ActionKind.Train);}
    [Fact]public void ForgedPreferredSkillCannotChangeRecordedChoice(){var s=new WorldSession(Start());At(s,20);var w=s.DiagnosticSnapshot();var d=w.NpcWork!.Decisions.First(d=>d.Inputs.Routine?.Purpose!=null);var p=d.Inputs.Routine!.Purpose!;w.NpcWork.Decisions[Array.IndexOf(w.NpcWork.Decisions,d)]=d with{Inputs=d.Inputs with{Routine=d.Inputs.Routine with{Purpose=p with{Skill=(DevelopmentSkill)(((int)p.Skill+1)%7)}}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void EventBudgetCannotPartiallyStartNpcPractice(){var s=new WorldSession(Start());At(s,7);s.SetPaused(false);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal("EventBudget",s.AdvanceTo(20,1).StopReason);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void DifferentAdvancePartitionsKeepTaskTimesAndExperience(){var a=new WorldSession(Start());var b=new WorldSession(Start());a.SetPaused(false);b.SetPaused(false);a.AdvanceTo(2000);foreach(long t in new long[]{1,7,9,20,170,451,1500,1815,2000})b.AdvanceTo(t);var x=a.DiagnosticSnapshot();var y=b.DiagnosticSnapshot();Assert.Equal(x.Requests.Select(r=>(r.Id,r.CreatedAt,r.Intent.Action,r.Intent.TrainingSkill)),y.Requests.Select(r=>(r.Id,r.CreatedAt,r.Intent.Action,r.Intent.TrainingSkill)));Assert.Equal(ContractJson.Write(x.Development),ContractJson.Write(y.Development));}
    [Fact]public void NpcPracticeIsNotEnabledByForgingAnOldPolicyRequest(){var s=new WorldSession(Start(policy:NewGameNpcRoutine.ContinuingPolicy));var i=CharacterDevelopment.Practice(s.DiagnosticSnapshot(),"request:forged-npc-practice",DevelopmentSkill.Tactics) with{Actor=Friend,Executor=Friend};Assert.Equal(ResultCode.InvalidInput,s.Submit(i,s.Revision).Code);}
    [Fact]public void OtherPeopleDoNotGainPrivateSkillValuesFromUnseenPractice(){var s=new WorldSession(Start());At(s,1900);var c=s.CharacterCard(Friend)!;Assert.False(c.Own);Assert.All(c.Skills,x=>Assert.Null(x.Value));Assert.All(c.Skills,x=>Assert.Equal(0,x.Experience));}
    [Fact]public void ActualCustodyPreventsDiscretionaryWorkUntilRelease(){var s=CustodySuccessionTests.Held(NewGameNpcRoutine.PurposePolicy);var actor=new EntityId("created:ward");int count=s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==actor);At(s,s.Seconds+86400);Assert.Equal(count,s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==actor));Assert.False(NewGameNpcRoutine.Inputs(s.DiagnosticSnapshot(),actor,s.Seconds,s.Revision).InspectionPermit);var root=s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;Good(s.ManageCustody(new(new("request:purpose-release"),CustodyAction.Release,Original:root),s.PlayerControl,s.Revision));At(s,s.Seconds+2000);Assert.True(s.DiagnosticSnapshot().Requests.Count(r=>r.Intent.Actor==actor)>count);new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)]
    public void ActualRecoveryKeepsDecisionPriorityAndSameFuture(int phase){var s=phase>=5?PracticingCompanion():new WorldSession(Start());if(phase==6){Good(s.ManageCompanion(new(new("request:purpose-recovery-trip"),Friend,CompanionAction.TravelTogether,Destination:"kofu"),s.PlayerControl,s.Revision));At(s,25);}else if(phase==5){Commission(s);At(s,23);}else At(s,phase switch{0=>1,1=>20,2=>1000,3=>1900,_=>86420});s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"npc-purpose-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"purpose",w.WorldId).Published);var host=new WorldSessionHost(new WorldSession(Start(phase>=5)));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("purpose"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,$"npc-purpose-{phase}.before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,$"npc-purpose-{phase}.restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+2000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
}
